from jsonb_to_recordset($wall_questions$[{"id":"u03_l04_q164","lesson_id":"u03_l04","difficulty":"medium","prompt":"إذا لم يوافق جميع الورثة على زيادة الوصية عن الثلث، فما الأصل الذي يرجع إليه؟","options":[{"id":"o1","text":"عدم تنفيذ الزيادة على الثلث دون رضاهم"},{"id":"o3","text":"إسقاط الوصية كلها ولو كانت دون الثلث"},{"id":"o2","text":"إلزام جميع الورثة بالزيادة مهما كانت"},{"id":"o4","text":"إعطاء الموصى له التركة كاملة"}],"correct_id":"o1","explanation":"شرط الكتاب موافقة جميع الورثة لتنفيذ ما زاد على الثلث.","page":116},{"id":"u03_l04_q167","lesson_id":"u03_l04","difficulty":"hard","prompt":"أي أثر تحققه كتابة الوصية والإشهاد عليها ولو كانت وصية صحيحة من حيث المقدار؟","options":[{"id":"o4","text":"تغيير الورثة الشرعيين بعد الوفاة"},{"id":"o1","text":"تقليل احتمالات جحودها والنزاع حول تنفيذها"},{"id":"o2","text":"إمكان مخالفة أحكام الإرث دون مراجعة"},{"id":"o3","text":"رفع قيد الثلث تلقائيًا"}],"correct_id":"o1","explanation":"علل الكتاب الكتابة والإشهاد بحفظ الحقوق وتفادي إنكار الوصية.","page":116},{"id":"u03_l04_q168","lesson_id":"u03_l04","difficulty":"medium","prompt":"ما نوع الوصية التي تتعلق بأداء الصلاة وصلة الرحم دون نقل مال؟","options":[{"id":"o4","text":"إعفاء مالي ملزم للغير"},{"id":"o2","text":"وصية بتوزيع الميراث"},{"id":"o1","text":"وصية بالنصيحة والخير والمعروف"},{"id":"o3","text":"بيع مؤجل إلى تاريخ الوفاة"}],"correct_id":"o1","explanation":"تحدث الإثراء عن وصية الإنسان أهله بالخير والمحافظة على العبادات والحقوق.","page":117},{"id":"u03_l04_q172","lesson_id":"u03_l04","difficulty":"medium","prompt":"ما الذي يجعل وصية لدعم دراسة أبناء الأسر المحتاجة مثالًا على التكافل الاجتماعي؟","options":[{"id":"o4","text":"أنها تلغي حق الفقير في المساعدة"},{"id":"o2","text":"أنها تحصر الثروة في يد وارث واحد"},{"id":"o3","text":"أنها تمنع طالب العلم من الاستفادة"},{"id":"o1","text":"أنها تمد المحتاجين بمنفعة بعد وفاة الموصي وتعينهم على التعلم"}],"correct_id":"o1","explanation":"ذكر الدرس تعليم طلبة العلم وكفالة الأيتام من وجوه الوصية التي تحقق التكافل.","page":115},{"id":"u03_l04_q174","lesson_id":"u03_l04","difficulty":"medium","prompt":"أوصى رجل بمبلغ يزيد على ثلث تركته؛ فبماذا يتوقف تنفيذ الزيادة؟","options":[{"id":"o2","text":"موافقة أحد الورثة دون الباقين"},{"id":"o3","text":"عدم وجود أي وصية مكتوبة"},{"id":"o1","text":"موافقة جميع الورثة على ما زاد على الثلث"},{"id":"o4","text":"مرور ثلاث سنوات على الوفاة"}],"correct_id":"o1","explanation":"أجاز الكتاب تنفيذ ما فوق الثلث إذا وافق جميع الورثة.","page":116},{"id":"u03_l04_q176","lesson_id":"u03_l04","difficulty":"medium","prompt":"إذا خصّ شخص أحد ورثته بوصية مالية بعد موته؛ فما الشرط الذي يجعل تنفيذها ممكنًا؟","options":[{"id":"o2","text":"موافقة الموصى له وحده"},{"id":"o4","text":"أن تكون مكتوبة دون اعتبار رضا الورثة"},{"id":"o1","text":"إجازة جميع الورثة بعد وفاته"},{"id":"o3","text":"عدم علم الورثة بالوصية"}],"correct_id":"o1","explanation":"تتوقف الوصية لوارث على موافقة بقية الورثة منعًا للنزاع.","page":116},{"id":"u03_l04_q181","lesson_id":"u03_l04","difficulty":"medium","prompt":"ما الذي يميز الوصية عن هبة تُنفذ فورًا أثناء حياة صاحب المال؟","options":[{"id":"o1","text":"تنفيذ التبرع الموصى به يكون بعد وفاة الموصي"},{"id":"o2","text":"يشترط في الوصية قبض المال في اللحظة نفسها"},{"id":"o3","text":"تنتقل الوصية دائمًا إلى أحد الورثة قبل الوفاة"},{"id":"o4","text":"لا يمكن تغيير الوصية في حياة صاحبها"}],"correct_id":"o1","explanation":"عرف الكتاب الوصية بتبرع في الحياة ينفذ بعد الوفاة.","page":115},{"id":"u03_l04_q183","lesson_id":"u03_l04","difficulty":"medium","prompt":"ما وجه التحريم إذا أوصى مالك ماله بقصد حرمان ورثته من حقهم؟","options":[{"id":"o1","text":"قصد الإضرار بالورثة يخالف ضوابط الوصية"},{"id":"o2","text":"كل وصية للفقراء تعد إضرارًا بالضرورة"},{"id":"o3","text":"نقل الملك بعد الوفاة يحرم دائمًا"},{"id":"o4","text":"الوصية لا تتصل بحقوق الورثة بأي وجه"}],"correct_id":"o1","explanation":"اشترط الكتاب ألا يقصد الموصي الإضرار بالورثة.","page":115},{"id":"u03_l04_q188","lesson_id":"u03_l04","difficulty":"hard","prompt":"كيف يختلف توجيه الأب أبناءه إلى صلة الرحم عن تخصيص مال بعد وفاته لصلة الرحم؟","options":[{"id":"o4","text":"كلاهما إلغاء تلقائي للميراث"},{"id":"o2","text":"الأول نقل فوري للملكية والثاني تحريم للنصيحة"},{"id":"o1","text":"الأول وصية بالنصيحة والثاني تصرف مالي مؤجل بعد الوفاة"},{"id":"o3","text":"كلاهما عقد زواج جديد"}],"correct_id":"o1","explanation":"عرض الإثراء الوصية بالمعروف والنصح إلى جانب الوصية بالمال.","page":117},{"id":"u03_l05_q107","lesson_id":"u03_l05","difficulty":"medium","prompt":"متى تأخذ البنت الواحدة نصف التركة وفق المثال المحدد؟","options":[{"id":"o3","text":"إذا كانت زوجة المتوفى فقط"},{"id":"o1","text":"إذا لم يكن للمتوفى غيرها من البنات ولا أبناء ذكور وفق الحالة المذكورة"},{"id":"o2","text":"إذا كان للمتوفى أبناء ذكور وبنات متعددات"},{"id":"o4","text":"إذا كانت أختًا للمتوفى دائمًا"}],"correct_id":"o1","explanation":"يورد الدرس نصيب البنت المنفردة دون ابن ذكر ضمن أمثلته.","page":123},{"id":"u03_l05_q109","lesson_id":"u03_l05","difficulty":"hard","prompt":"أي مثال يرد على القول إن نصيب الأنثى نصف نصيب الذكر في كل حالات الميراث؟","options":[{"id":"o3","text":"أن الزوجة لا ترث من زوجها مطلقًا"},{"id":"o4","text":"أن البنات لا يرثن بوجود أي وارث آخر"},{"id":"o2","text":"أن الذكر يأخذ ضعف الأنثى في جميع الحالات"},{"id":"o1","text":"تساوي الأب والأم في السدس إذا توفي ابنهما وترك أولادًا"}],"correct_id":"o1","explanation":"أورد الكتاب حالة تساوي الأب والأم لإيضاح تنوع الأنصبة.","page":123},{"id":"u03_l05_q114","lesson_id":"u03_l05","difficulty":"medium","prompt":"ما حكم القتل الخطأ في أثره على حق الميراث؟","options":[{"id":"o2","text":"يمنع القتل الخطأ الميراث دائمًا"},{"id":"o4","text":"يُغيّر سبب الميراث من الزوجية إلى القرابة"},{"id":"o1","text":"لا يمنع القتل الخطأ من الميراث"},{"id":"o3","text":"يُسقط نصيب جميع الورثة"}],"correct_id":"o1","explanation":"فرّق الدرس بين القتل العمد المانع من الإرث والقتل الخطأ غير المانع.","page":121},{"id":"u03_l05_q122","lesson_id":"u03_l05","difficulty":"medium","prompt":"لماذا يوزَّع المال الموروث على مستحقيه وفق قواعد محددة؟","options":[{"id":"o3","text":"لإلغاء صلة الرحم"},{"id":"o4","text":"لترك القسمة لرغبة شخص واحد"},{"id":"o1","text":"لمنع التنازع وبيان حقوق ذوي الصلة بالميت"},{"id":"o2","text":"لإعطاء المال لمن يطلبه أولًا"}],"correct_id":"o1","explanation":"أبرز الدرس منع النزاع وتحقيق العدل وصلة الرحم في تنظيم الإرث.","page":120},{"id":"u03_l05_q124","lesson_id":"u03_l05","difficulty":"medium","prompt":"ما أول إجراء مالي يتعلق بتركة الميت قبل سداد ديونه وتقسيم إرثه؟","options":[{"id":"o4","text":"توزيع الهدايا على الجيران"},{"id":"o2","text":"إعطاء الورثة حصصهم فورًا"},{"id":"o3","text":"تنفيذ الوصية قبل أي شيء"},{"id":"o1","text":"إخراج نفقات تجهيزه ودفنه"}],"correct_id":"o1","explanation":"قدم الكتاب نفقات التجهيز والدفن على الدين والوصية والتوزيع.","page":121},{"id":"u03_l05_q132","lesson_id":"u03_l05","difficulty":"medium","prompt":"كيف يسهم تحديد أنصبة الورثة سلفًا في تحقيق استقرار الأسرة؟","options":[{"id":"o1","text":"يحد من النزاع والاعتداء على الحقوق"},{"id":"o3","text":"يجعل المال حكرًا للأقوى"},{"id":"o2","text":"يزيد الغموض عند تقسيم المال"},{"id":"o4","text":"يلغي صلة القرابة"}],"correct_id":"o1","explanation":"يذكر الدرس أن معرفة المستحقين تحفظ العلاقات والحقوق.","page":120},{"id":"u03_l05_q142","lesson_id":"u03_l05","difficulty":"medium","prompt":"كيف يسهم تشريع الميراث في منع احتكار الثروة في الأسرة؟","options":[{"id":"o2","text":"بحرمان الأقارب من جميع الأموال"},{"id":"o3","text":"بجمع المال عند شخص واحد دائمًا"},{"id":"o4","text":"بمنع الورثة من معرفة أنصبتهم"},{"id":"o1","text":"بتوزيع الأموال على مستحقيها بدل حصرها في فئة واحدة"}],"correct_id":"o1","explanation":"عدّ الكتاب توزيع الثروة ومنع تجمعها لدى فئة محددة من حكم الميراث.","page":120},{"id":"u03_l05_q152","lesson_id":"u03_l05","difficulty":"hard","prompt":"إذا تأخرت الأسرة عن سداد دين على المتوفى ووزعت التركة كلها، فما الخلل في ترتيب الحقوق؟","options":[{"id":"o1","text":"تقديم حصص الورثة على دين واجب السداد أولًا"},{"id":"o2","text":"تقديم قضاء الدين على تنفيذ الوصية"},{"id":"o3","text":"تجهيز المتوفى قبل القسمة"},{"id":"o4","text":"التثبت من وجود الوصية الصحيحة"}],"correct_id":"o1","explanation":"رتّب الكتاب الحقوق بدءًا بالتجهيز ثم الدين فالوصية ثم توزيع الباقي.","page":121},{"id":"u03_l05_q154","lesson_id":"u03_l05","difficulty":"medium","prompt":"ما الذي يميّز القتل الخطأ من القتل العمد في أثره على الإرث؟","options":[{"id":"o4","text":"القتل الخطأ ينقل الحق إلى الجيران"},{"id":"o2","text":"كلاهما يمنع الإرث بالقدر نفسه"},{"id":"o1","text":"القتل الخطأ لا يمنع الإرث كما يمنعه القتل العمد"},{"id":"o3","text":"القتل الخطأ يزيد نصيب الوارث"}],"correct_id":"o1","explanation":"نص الكتاب على أن القتل العمد مانع للميراث بخلاف القتل الخطأ.","page":121},{"id":"u03_l05_q158","lesson_id":"u03_l05","difficulty":"hard","prompt":"ما الذي يفسر خطأ الجملة القائلة إن نصيب المرأة نصف نصيب الرجل في جميع حالات الميراث؟","options":[{"id":"o4","text":"أن كل الورثة يأخذون أنصبة متماثلة"},{"id":"o3","text":"أن للمرأة نصيبًا واحدًا ثابتًا في كل الأسر"},{"id":"o1","text":"أن النصيب قد يتساوى أو يزيد بحسب القرابة والورثة والحالة"},{"id":"o2","text":"أن الميراث لا يتأثر بوجود أبناء مطلقًا"}],"correct_id":"o1","explanation":"أورد الكتاب حالات المساواة وزيادة نصيب بعض النساء على بعض الرجال في الميراث.","page":123},{"id":"u03_l05_q164","lesson_id":"u03_l05","difficulty":"hard","prompt":"لماذا يسبق سداد الدين تنفيذ الوصية في ترتيب الحقوق المتعلقة بالتركة؟","options":[{"id":"o3","text":"لأن الدين يصير تبرعًا بعد الوفاة"},{"id":"o1","text":"لأنه حق واجب في ذمة المتوفى يُقضى قبل التبرع"},{"id":"o4","text":"لأن الورثة لا يتحملون أي واجب تجاه التركة"},{"id":"o2","text":"لأن الوصية غير مشروعة دائمًا"}],"correct_id":"o1","explanation":"قرر الكتاب تقديم تجهيز الميت ثم سداد الديون فالوصية ثم التوزيع.","page":121},{"id":"u03_l05_q165","lesson_id":"u03_l05","difficulty":"medium","prompt":"ما الذي يستفيده الورثة من قاعدة حرمان من يتعمد قتل مورثه؟","options":[{"id":"o2","text":"أن قتل المورث يزيد نصيب القاتل"},{"id":"o1","text":"ألا تتحول الرغبة في المال إلى حافز للاعتداء"},{"id":"o4","text":"أن تقسيم المال يسبق تجهيز الميت"},{"id":"o3","text":"أن القتل الخطأ يساوي العمد في جميع أحكام الإرث"}],"correct_id":"o1","explanation":"ذكر الدرس أن المنع يردع الاعتداء لاستعجال الإرث.","page":121},{"id":"u03_l05_q166","lesson_id":"u03_l05","difficulty":"hard","prompt":"إذا ترك المتوفى أبناء ذكورًا وإخوة أشقاء؛ فما أثر ذلك على حق الإخوة بحسب المثال المدرسي؟","options":[{"id":"o4","text":"لا أثر لوجود الأبناء على الإخوة"},{"id":"o2","text":"يأخذ الإخوة كل الميراث دون الأبناء"},{"id":"o1","text":"يُحجب الإخوة بالأبناء الذكور ولا يرثون"},{"id":"o3","text":"يتساوى نصيب كل أخ مع نصيب كل ابن"}],"correct_id":"o1","explanation":"أوضح الكتاب حجب الإخوة بالأبناء الذكور عند اجتماعهم.","page":122},{"id":"u03_l05_q172","lesson_id":"u03_l05","difficulty":"medium","prompt":"كيف يسهم توزيع التركة بين المستحقين في تحقيق التكافل؟","options":[{"id":"o4","text":"يجيز الاعتداء على نصيب الورثة الضعفاء"},{"id":"o2","text":"يجعل جميع الأموال ملكًا لشخص واحد دائمًا"},{"id":"o3","text":"يلغي روابط القرابة والزوجية"},{"id":"o1","text":"يمنع حصر الثروة في يد فئة ويحدد الحقوق بين أفراد الأسرة"}],"correct_id":"o1","explanation":"بيّن الكتاب أن نظام الميراث يعزز العدل والتآلف ويمنع احتكار الثروة.","page":120},{"id":"u03_l05_q181","lesson_id":"u03_l05","difficulty":"medium","prompt":"ما الأثر الاجتماعي لتوزيع التركة بدل تركيزها في يد فئة واحدة؟","options":[{"id":"o2","text":"حرمان أصحاب الحقوق من أنصبتهم"},{"id":"o3","text":"توسيع الخصومات على الأموال"},{"id":"o4","text":"إلغاء مسؤولية الوارث عن احترام حقوق غيره"},{"id":"o1","text":"تقليل احتكار الثروة وتعزيز الروابط الأسرية"}],"correct_id":"o1","explanation":"ذكر الكتاب انتشار الثروة وتقوية الروابط من حكم الميراث.","page":120},{"id":"u03_l05_q183","lesson_id":"u03_l05","difficulty":"medium","prompt":"ما الحق الذي يقدم على تنفيذ وصية الميت عند ترتيب الحقوق المالية في التركة؟","options":[{"id":"o4","text":"إقامة الاحتفالات الباهظة على نفقة التركة"},{"id":"o1","text":"سداد ديونه بعد تكاليف تجهيزه ودفنه"},{"id":"o2","text":"توزيع أنصبة الورثة فورًا قبل كل التزام"},{"id":"o3","text":"منح الهدايا الاختيارية للزوار"}],"correct_id":"o1","explanation":"رتب الكتاب تجهيز الميت وسداد الدين ثم الوصية ثم التوزيع.","page":121},{"id":"u03_l05_q187","lesson_id":"u03_l05","difficulty":"medium","prompt":"ماذا يفسر حصول الأبناء أحيانًا على أنصبة أكبر من الآباء مع اختلاف المسؤوليات؟","options":[{"id":"o4","text":"أن المسؤولية لا تؤثر في أي توزيع"},{"id":"o3","text":"أن المال يتبع العمر وحده دون أحكام"},{"id":"o1","text":"تفاوت الحاجة والالتزامات بحسب المرحلة الحياتية"},{"id":"o2","text":"أن الآباء لا يدخلون ضمن الورثة"}],"correct_id":"o1","explanation":"عدد الدرس مراعاة المسؤوليات والحاجة إلى المال ضمن أسس الميراث.","page":122},{"id":"u03_l05_q188","lesson_id":"u03_l05","difficulty":"hard","prompt":"ما الذي يفند القول إن كل امرأة تأخذ دائمًا نصف ما يأخذه الرجل في جميع مسائل الميراث؟","options":[{"id":"o1","text":"وجود حالات تساوي الأنصبة أو تزيد فيها حصة المرأة"},{"id":"o3","text":"أنصبة الإرث لا تتصل بالقرابة"},{"id":"o2","text":"وجود قاعدة تمنع النساء من الميراث"},{"id":"o4","text":"أن جميع الرجال يحصلون على نصيب واحد"}],"correct_id":"o1","explanation":"أورد الكتاب حالات مساواة أو زيادة نصيب المرأة بحسب صورة الورثة.","page":123},{"id":"u03_l06_q105","lesson_id":"u03_l06","difficulty":"medium","prompt":"ما دلالة التوجيه النبوي بالتيسير دون تعسير؟","options":[{"id":"o1","text":"اتباع الاعتدال في تبليغ الدين والتعامل مع الناس"},{"id":"o4","text":"إبطال الأخذ بالأسباب"},{"id":"o3","text":"التشدد على الناس في كل شأن"},{"id":"o2","text":"التهاون في الفرائض"}],"correct_id":"o1","explanation":"أورد الدرس الحديث للدلالة على الرفق والاعتدال.","page":126},{"id":"u03_l06_q106","lesson_id":"u03_l06","difficulty":"medium","prompt":"لماذا نهى النبي ﷺ عن الإطالة التي تشق على المصلين في الجماعة؟","options":[{"id":"o3","text":"لأن جميع المصلين لهم قدرة واحدة"},{"id":"o2","text":"لأن صلاة الجماعة غير مشروعة"},{"id":"o4","text":"لإلغاء الصلاة المفروضة"},{"id":"o1","text":"لمراعاة الضعيف والكبير وصاحب الحاجة"}],"correct_id":"o1","explanation":"أورد الكتاب الحديث مثالًا للوسطية في العبادات.","page":128},{"id":"u03_l06_q108","lesson_id":"u03_l06","difficulty":"medium","prompt":"كيف توازن الشريعة بين الملكية الفردية والمصلحة العامة في المعاملات المالية؟","options":[{"id":"o4","text":"تلغي التزامات الأفراد المالية تجاه المجتمع"},{"id":"o1","text":"تقر الكسب والملكية بضوابط تمنع الاستغلال والضرر"},{"id":"o2","text":"تمنع كل ملكية فردية"},{"id":"o3","text":"تسمح باستغلال الجميع بلا قيود"}],"correct_id":"o1","explanation":"بيّن الكتاب حماية الملكية مع منع الاستغلال والضرر.","page":128},{"id":"u03_l06_q114","lesson_id":"u03_l06","difficulty":"medium","prompt":"لماذا نهى النبي ﷺ عن الوصال في الصيام ضمن مظاهر الوسطية؟","options":[{"id":"o4","text":"لأن أي تطوع ممنوع مطلقًا"},{"id":"o2","text":"لإبطال الصيام كله"},{"id":"o3","text":"لجعل الصيام بديلًا عن الصلاة"},{"id":"o1","text":"لمنع تحميل النفس مشقة غير مطلوبة"}],"correct_id":"o1","explanation":"ساق الدرس النهي عن الوصال مثالًا للوسطية في العبادات.","page":128},{"id":"u03_l06_q124","lesson_id":"u03_l06","difficulty":"medium","prompt":"كيف تظهر الوسطية في النظر إلى الرسل في العقيدة الإسلامية؟","options":[{"id":"o4","text":"إنكار أنهم بشر مصطفون"},{"id":"o2","text":"اعتبارهم آلهة مستقلة"},{"id":"o3","text":"الاستخفاف بجميع رسالاتهم"},{"id":"o1","text":"احترامهم والإيمان بهم دون تأليههم"}],"correct_id":"o1","explanation":"عرض الدرس احترام الأنبياء مع رفض الغلو في تأليههم.","page":127},{"id":"u03_l06_q126","lesson_id":"u03_l06","difficulty":"medium","prompt":"أي عبارة من منهج الوسطية تجمع بين التوكل والأخذ بالأسباب؟","options":[{"id":"o1","text":"الاجتهاد فيما ينفع والاستعانة بالله دون عجز"},{"id":"o4","text":"التسليم للفشل دون محاولة"},{"id":"o2","text":"ترك الدراسة والعمل والاكتفاء بالتمني"},{"id":"o3","text":"الاعتماد على الأسباب مع إنكار التوكل"}],"correct_id":"o1","explanation":"استشهد الكتاب بالتوجيه النبوي للحرص على النافع والاستعانة بالله.","page":127},{"id":"u03_l06_q129","lesson_id":"u03_l06","difficulty":"hard","prompt":"كيف تجسدت الوسطية في موقف الشريعة من الطلاق؟","options":[{"id":"o2","text":"منعته في كل الأحوال"},{"id":"o1","text":"أباحته عند الحاجة بضوابط ولم تتركه مطلقًا بلا قيد"},{"id":"o3","text":"أباحته دون أي قيود"},{"id":"o4","text":"جعلته واجبًا عند أي نقاش"}],"correct_id":"o1","explanation":"قارن النص بين منع الطلاق المطلق وإباحته المنفلتة وبيّن موقفًا وسطًا.","page":129},{"id":"u03_l06_q131","lesson_id":"u03_l06","difficulty":"medium","prompt":"أي وصف للوسطية يميزها عن التساهل في تنفيذ الأوامر الشرعية؟","options":[{"id":"o1","text":"اعتدال منضبط بالحق دون إفراط أو تفريط"},{"id":"o4","text":"مساواة الحلال بالحرام"},{"id":"o2","text":"ترك الواجب عند كل مشقة بسيطة"},{"id":"o3","text":"تقديم العرف على جميع الأحكام"}],"correct_id":"o1","explanation":"عرّف الكتاب الوسطية بأنها المنهج المعتدل الموافق للشرع.","page":126},{"id":"u03_l06_q135","lesson_id":"u03_l06","difficulty":"medium","prompt":"لماذا نهى النبي ﷺ عن إطالة صلاة الجماعة التي تشق على الضعفاء؟","options":[{"id":"o4","text":"لأن إمام الجماعة لا يصلي"},{"id":"o3","text":"لأن جميع المصلين أقوياء"},{"id":"o1","text":"لمراعاة أحوال المصلين وقدراتهم"},{"id":"o2","text":"لإلغاء الخشوع في الصلاة"}],"correct_id":"o1","explanation":"ذكر الدرس مراعاة الضعيف والكبير وصاحب الحاجة.","page":128},{"id":"u03_l06_q142","lesson_id":"u03_l06","difficulty":"medium","prompt":"لماذا لا تعني الوسطية ترك الالتزام بالتكاليف الشرعية لتجنب المشقة؟","options":[{"id":"o2","text":"لأنها تلغي الحدود الشرعية جميعها"},{"id":"o4","text":"لأن كل التزام يُعد إفراطًا"},{"id":"o1","text":"لأنها أداء الواجبات دون غلو أو تهاون"},{"id":"o3","text":"لأن التهاون هو الصورة الوحيدة للوسطية"}],"correct_id":"o1","explanation":"نص الدرس على الجمع بين أداء الواجبات وعدم التشدد أو التفريط.","page":126},{"id":"u03_l06_q143","lesson_id":"u03_l06","difficulty":"hard","prompt":"شخص يرفض أسباب الرزق مكتفيًا بالدعاء، وآخر ينفي أثر التوكل ويعتمد على جهده وحده؛ ما البديل الوسطي؟","options":[{"id":"o4","text":"ترك الأسباب لحين ظهور نتيجة"},{"id":"o2","text":"إهمال العمل والدعاء معًا"},{"id":"o1","text":"العمل بالأسباب مع التوكل الصادق على الله"},{"id":"o3","text":"الاعتماد على المصادفة وحدها"}],"correct_id":"o1","explanation":"جمع الدرس بين الأخذ بالأسباب النافعة والتوكل على الله.","page":127},{"id":"u03_l06_q145","lesson_id":"u03_l06","difficulty":"medium","prompt":"ما المقصد من تخفيف الإمام صلاته عند وجود ضعفاء وكبار سن في الجماعة؟","options":[{"id":"o4","text":"حصر الصلاة في الأصحاء"},{"id":"o3","text":"إطالة القراءة عمدًا لإظهار التفوق"},{"id":"o1","text":"مراعاة أحوال المصلين ودفع المشقة"},{"id":"o2","text":"إلغاء الصلاة عن الجماعة"}],"correct_id":"o1","explanation":"ذكر الدرس حديث الأمر بالتخفيف مراعاة لقدرات المصلين.","page":128},{"id":"u03_l06_q148","lesson_id":"u03_l06","difficulty":"medium","prompt":"ما أثر الوسطية على قدرة الناس على الاستمرار في أداء التكاليف الشرعية؟","options":[{"id":"o4","text":"إلغاء التدرج في التعلم"},{"id":"o2","text":"تكليفهم فوق طاقتهم باستمرار"},{"id":"o3","text":"استبدال الواجبات بالمظاهر"},{"id":"o1","text":"مراعاة طاقتهم بما يعينهم على الالتزام"}],"correct_id":"o1","explanation":"ذكر الكتاب أن أحكام الوسطية تراعي الوسع والطاقة وتسهّل الالتزام.","page":130},{"id":"u03_l06_q153","lesson_id":"u03_l06","difficulty":"hard","prompt":"لماذا لا يصح اعتبار التطوع الذي يستنفد الصحة ويعطل حقوق الأسرة نموذجًا للاعتدال؟","options":[{"id":"o4","text":"لأن كل عبادة تطوعية ممنوعة"},{"id":"o1","text":"لأن الوسطية تحفظ حقوق النفس والأهل وتمنع الغلو"},{"id":"o2","text":"لأن القيام والطاعة لا علاقة لهما بالواجبات"},{"id":"o3","text":"لأن حقوق الأسرة تلغى مع زيادة التطوع"}],"correct_id":"o1","explanation":"استشهد الدرس بحفظ حقوق النفس والأهل ونهي النبي ﷺ عن التشدد.","page":128},{"id":"u03_l06_q154","lesson_id":"u03_l06","difficulty":"medium","prompt":"ما وجه الوسطية في إمامة الصلاة إذا ضمّت الجماعة ضعفاء وأصحاب حاجات؟","options":[{"id":"o3","text":"منع الكبار من أداء الصلاة مع الجماعة"},{"id":"o1","text":"مراعاة أحوال المصلين وتخفيف ما يشق عليهم"},{"id":"o2","text":"إطالة القراءة عمدًا لإرهاق الجميع"},{"id":"o4","text":"جعل الصلاة سببًا لتعطيل واجبات الناس"}],"correct_id":"o1","explanation":"ذكر الكتاب توجيه النبي ﷺ لتخفيف الصلاة الجماعية مراعاة للضعفاء والمحتاجين.","page":128},{"id":"u03_l06_q166","lesson_id":"u03_l06","difficulty":"medium","prompt":"ما المنفعة التي يراعيها الإمام عند عدم إطالة صلاة الجماعة؟","options":[{"id":"o1","text":"أحوال الضعفاء وكبار السن وأصحاب الحاجات"},{"id":"o3","text":"تضييق الوقت على المأمومين"},{"id":"o2","text":"إظهار قدرته على الإطالة وحدها"},{"id":"o4","text":"منع أصحاب الحاجات من الصلاة"}],"correct_id":"o1","explanation":"أورد الدرس الأمر بتخفيف إمامة الصلاة مراعاة لأحوال المصلين.","page":128},{"id":"u03_l06_q172","lesson_id":"u03_l06","difficulty":"medium","prompt":"ما ضابط اختيار الأيسر في هدي النبي ﷺ كما جاء في حديث عائشة رضي الله عنها؟","options":[{"id":"o1","text":"أن يكون الأيسر غير مشتمل على إثم"},{"id":"o2","text":"أن يوافق الرغبة الشخصية مهما كان الحكم"},{"id":"o4","text":"أن يكون أشد ضررًا بالآخرين"},{"id":"o3","text":"أن يترك جميع الواجبات"}],"correct_id":"o1","explanation":"ذكر الحديث أن النبي ﷺ اختار الأيسر ما لم يكن إثمًا.","page":126},{"id":"u03_l06_q174","lesson_id":"u03_l06","difficulty":"medium","prompt":"أي سلوك يوضح الجمع بين التوكل على الله والأخذ بالأسباب؟","options":[{"id":"o4","text":"الاستسلام للفشل قبل بذل أي جهد"},{"id":"o1","text":"الاستعداد للاختبار بالمذاكرة مع الاستعانة بالله"},{"id":"o3","text":"الاعتماد على الوسائل وحدها ونفي التوكل"},{"id":"o2","text":"الامتناع عن الدراسة وانتظار النجاح"}],"correct_id":"o1","explanation":"قرّر الدرس أن الوسطية تجمع الأخذ بالأسباب النافعة مع التوكل الصادق.","page":127},{"id":"u03_l06_q175","lesson_id":"u03_l06","difficulty":"easy","prompt":"لماذا يُخفّف الإمام صلاة الجماعة إذا كان بين المصلين كبار وضعفاء وأصحاب حاجات؟","options":[{"id":"o2","text":"لأن الجماعة لا تتضمن أركانًا واجبة"},{"id":"o3","text":"لأن طول الصلاة مطلوب دائمًا مهما شق"},{"id":"o1","text":"مراعاة أحوال المصلين وقدراتهم"},{"id":"o4","text":"لأن الإمام يملك إسقاط الصلاة عن الحاضرين"}],"correct_id":"o1","explanation":"استدل الدرس بحديث التخفيف مراعاة للضعيف والكبير وذي الحاجة.","page":128},{"id":"u03_l06_q181","lesson_id":"u03_l06","difficulty":"medium","prompt":"ما معنى الوسطية إذا كان الإنسان يستطيع أداء واجبه من غير مشقة غير معتادة؟","options":[{"id":"o3","text":"ترك الواجب كله طلبًا للراحة"},{"id":"o1","text":"اتباع المنهج المعتدل الذي يراعي الطاقة والحق"},{"id":"o2","text":"البحث عن أشد تكليف ممكن دائمًا"},{"id":"o4","text":"الاقتصار على رأي الشخص دون نص"}],"correct_id":"o1","explanation":"عرّف الكتاب الوسطية بالمنهج الحق المعتدل الملائم للإنسان.","page":126},{"id":"u03_l06_q182","lesson_id":"u03_l06","difficulty":"hard","prompt":"كيف يختلف توحيد الله عن إنكار وجوده أو القول بتعدد الآلهة في عرض وسطية الاعتقاد؟","options":[{"id":"o3","text":"يجيز تعدد الآلهة لكل ظاهرة كونية"},{"id":"o4","text":"يستغني عن أي عقيدة لتأسيس الإيمان"},{"id":"o1","text":"يثبت الإله الواحد وينفي الإنكار والشرك"},{"id":"o2","text":"يجعل إنكار الخالق والتوحيد موقفًا واحدًا"}],"correct_id":"o1","explanation":"عرض الدرس توحيد الله بوصفه وسطًا بين إنكار وجوده والقول بتعدد الآلهة.","page":127},{"id":"u03_l07_q109","lesson_id":"u03_l07","difficulty":"hard","prompt":"ما الفرق الجوهري بين الانتفاع المستمر بالوقف والتصرف في أصله كما يريد صاحبه؟","options":[{"id":"o2","text":"يصبح الأصل قابلًا للبيع كل يوم بلا قيد"},{"id":"o3","text":"يلغي الوقف دور المنفعة في المجتمع"},{"id":"o1","text":"يثبت أصل الوقف وتوجه منفعته للخير ولا يُباع أو يوهب كالمعتاد"},{"id":"o4","text":"لا يحتاج الوقف إلى استمرار أو تخصيص"}],"correct_id":"o1","explanation":"عرّف الكتاب الوقف بحبس الأصل وتوجيه ريعه مع نية الدوام.","page":133},{"id":"u03_l07_q115","lesson_id":"u03_l07","difficulty":"medium","prompt":"ما الذي ميّز المستشفى المنصوري الموقوف في القاهرة؟","options":[{"id":"o4","text":"عدم تخصيص أي مال لتشغيله"},{"id":"o2","text":"اقتصاره على علاج الأثرياء"},{"id":"o1","text":"العلاج المجاني ووجود مدرسة لتدريس الطب"},{"id":"o3","text":"إغلاقه أمام طلبة الطب"}],"correct_id":"o1","explanation":"ذكر الدرس العلاج المجاني ومصاريفه الدائمة والمدرسة الطبية.","page":135},{"id":"u03_l07_q120","lesson_id":"u03_l07","difficulty":"hard","prompt":"مؤسسة خصصت منصة تعليمية مجانية على الدوام ولم تبع أصلها؛ بأي وجه يوافق ذلك مفهوم الوقف الحديث؟","options":[{"id":"o1","text":"تخصيص أصل إلكتروني لمنفعة خيرية مستمرة"},{"id":"o3","text":"اشتراط الربح الفردي من المنصة فقط"},{"id":"o4","text":"بيع المحتوى الموقوف كلما ارتفع سعره"},{"id":"o2","text":"إنهاء حق الانتفاع كل يوم"}],"correct_id":"o1","explanation":"يجمع المثال بين دوام منفعة الأصل الموقوف وتعريف الوقف الإلكتروني في التوسع.","page":133},{"id":"u03_l07_q121","lesson_id":"u03_l07","difficulty":"medium","prompt":"ما الذي يميز الوقف عن التبرع الذي ينتقل أصله ملكًا للمنتفع؟","options":[{"id":"o3","text":"إلغاء أي استفادة من المال الموقوف"},{"id":"o1","text":"حبس الأصل وتخصيص ريعه أو منفعته للخير على وجه مستمر"},{"id":"o2","text":"بيع الأصل كل عام وتوزيع ثمنه"},{"id":"o4","text":"اقتصار الوقف على الطعام القابل للتلف"}],"correct_id":"o1","explanation":"عرّف الكتاب الوقف بحبس الأصل وصرف منفعته في وجه الخير.","page":133},{"id":"u03_l07_q124","lesson_id":"u03_l07","difficulty":"medium","prompt":"ما القاسم المشترك بين المكتبات وأماكن المبيت الملحقة بالمدارس الموقوفة؟","options":[{"id":"o4","text":"حصر النشاط في العلاج الطبي"},{"id":"o2","text":"تحويل التعليم إلى امتياز للأغنياء فقط"},{"id":"o1","text":"تيسير طلب العلم وإقامة بيئة مناسبة للطلاب"},{"id":"o3","text":"الاستغناء عن الكتب والمعلمين"}],"correct_id":"o1","explanation":"عرض الكتاب دعم الوقف العلمي لبيئة الطلاب بالدراسة والسكن والكتب.","page":134},{"id":"u03_l07_q128","lesson_id":"u03_l07","difficulty":"medium","prompt":"ما نوع الخدمة التي تقدمها التكايا الموقوفة في المجال الاجتماعي؟","options":[{"id":"o3","text":"إصدار قرارات المحاكم"},{"id":"o2","text":"تدريس الطب الجراحي حصريًا"},{"id":"o1","text":"توزيع الطعام مجانًا على المحتاجين"},{"id":"o4","text":"تسجيل أنصبة الميراث"}],"correct_id":"o1","explanation":"ذكر الدرس وقف التكايا لتقديم الطعام للمحتاجين.","page":136},{"id":"u03_l07_q131","lesson_id":"u03_l07","difficulty":"medium","prompt":"وقف رجل أصل مال ينتفع بثمرته الفقراء دون بيعه؛ أي قيد في تعريف الوقف يتحقق؟","options":[{"id":"o4","text":"اشتراط الربح الشخصي للموقف"},{"id":"o2","text":"نقل الأصل إلى البيع التجاري فورًا"},{"id":"o3","text":"انتهاء الخير بموت أول مستفيد"},{"id":"o1","text":"بقاء الأصل وتخصيص منفعته في الخير"}],"correct_id":"o1","explanation":"عرّف الدرس الوقف بتخصيص أصل للانتفاع المستمر ومنع بيعه وهبته.","page":133},{"id":"u03_l07_q133","lesson_id":"u03_l07","difficulty":"medium","prompt":"لماذا عُدت المدارس والمكتبات من أهم مجالات الوقف العلمي؟","options":[{"id":"o2","text":"لأنها توقف العلاج الصحي"},{"id":"o4","text":"لأنها تقتصر على التجارة"},{"id":"o3","text":"لأنها تمنع الدراسة المجانية"},{"id":"o1","text":"لإتاحتها التعليم وحفظ العقل ونشر المعرفة"}],"correct_id":"o1","explanation":"ذكر الدرس أن الوقف العلمي يساهم في تنمية العقل والمعرفة.","page":134},{"id":"u03_l07_q139","lesson_id":"u03_l07","difficulty":"medium","prompt":"ما الفرق الأساسي بين وقف مكتبة إلكترونية وبين بيع كتبها للربح الشخصي؟","options":[{"id":"o4","text":"التصرف بالوقف لإثراء صاحبه"},{"id":"o2","text":"احتكار الكتب لمن يدفع أكثر"},{"id":"o1","text":"تخصيص منفعة الأصول الرقمية المستمرة للخير"},{"id":"o3","text":"قطع الوصول إلى المعرفة"}],"correct_id":"o1","explanation":"عرّف الدرس الوقف الإلكتروني بوقف أصول تقنية وجعل منافعها للخير.","page":137},{"id":"u03_l07_q140","lesson_id":"u03_l07","difficulty":"hard","prompt":"أنشأت مؤسسة قناة رقمية لتعليم القرآن مجانًا وجعلت استمراريتها هدفًا ثابتًا؛ فأي مجال حديث يمثل مشروعها؟","options":[{"id":"o3","text":"الوصية لوارث"},{"id":"o1","text":"الوقف الإلكتروني التعليمي"},{"id":"o2","text":"الوقف العسكري التقليدي"},{"id":"o4","text":"التجارة الخاصة غير الخيرية"}],"correct_id":"o1","explanation":"ذكر الإثراء القنوات والمقارئ الإلكترونية مثالًا للوقف الرقمي.","page":137},{"id":"u03_l07_q142","lesson_id":"u03_l07","difficulty":"medium","prompt":"لماذا كان الوقف على المدارس والمكتبات وسيلة مباشرة لخدمة مقصد حفظ العقل؟","options":[{"id":"o1","text":"لأنه يتيح التعلم والكتب والبحث ونشر المعرفة"},{"id":"o4","text":"لأنه يلغي المؤسسات التعليمية"},{"id":"o2","text":"لأنه يمنع الاطلاع على المعارف"},{"id":"o3","text":"لأنه يحصر التعليم في الأثرياء"}],"correct_id":"o1","explanation":"شرح الدرس أن الوقف العلمي يعزز العلم ويخدم حفظ العقل.","page":134},{"id":"u03_l07_q144","lesson_id":"u03_l07","difficulty":"medium","prompt":"ما الذي جعل المستشفى المنصوري في القاهرة مثالًا للوقف الصحي المتكامل؟","options":[{"id":"o4","text":"استعماله للأغراض العسكرية حصريًا"},{"id":"o1","text":"تمويل علاج المرضى وإقامة مدرسة لتعليم الطب"},{"id":"o3","text":"منعه الدراسة الطبية"},{"id":"o2","text":"اقتصاره على خدمة التجار فقط"}],"correct_id":"o1","explanation":"وصف الكتاب المستشفى المنصوري وخدمات العلاج والتعليم الطبي.","page":135},{"id":"u03_l07_q145","lesson_id":"u03_l07","difficulty":"medium","prompt":"أي أثر للتكامل بين الوقف الصحي والتعليم الطبي ورد في الأمثلة؟","options":[{"id":"o4","text":"إلغاء تمويل الخدمات الصحية"},{"id":"o1","text":"توفير رعاية المرضى مع إعداد من يدرس الطب"},{"id":"o3","text":"فصل الصحة تمامًا عن العلم"},{"id":"o2","text":"الحد من عدد المتعلمين والأطباء"}],"correct_id":"o1","explanation":"ذكر الدرس مستشفيات ومدارس طبية وقفية تخدم المرضى وطلاب الطب.","page":135},{"id":"u03_l07_q147","lesson_id":"u03_l07","difficulty":"easy","prompt":"أي خدمة تقدمها التكايا الوقفية؟","options":[{"id":"o3","text":"حساب أنصبة الورثة"},{"id":"o1","text":"إطعام المحتاجين وتقديم خدمات اجتماعية"},{"id":"o2","text":"تحديد أحكام الوصية"},{"id":"o4","text":"إصدار أحكام القضاء"}],"correct_id":"o1","explanation":"ذكر الكتاب التكايا التي توزع الطعام على المحتاجين مجانًا.","page":136},{"id":"u03_l07_q148","lesson_id":"u03_l07","difficulty":"medium","prompt":"ما الذي يجعل مكتبة رقمية نافعة مثالًا للوقف الإلكتروني لا لمجرد موقع تجاري؟","options":[{"id":"o2","text":"حصر موادها في البيع الخاص دون وجه وقف"},{"id":"o4","text":"تغيير رسالتها إلى إعلان تجاري حصري"},{"id":"o1","text":"تخصيص أصل رقمي ومنفعته المستمرة لإفادة الناس"},{"id":"o3","text":"إغلاق محتواها أمام طلبة العلم"}],"correct_id":"o1","explanation":"عرّف الدرس الوقف الإلكتروني بتخصيص أصول ومواقع ومواد تقنية لخدمة الناس.","page":137},{"id":"u03_l07_q153","lesson_id":"u03_l07","difficulty":"hard","prompt":"ما الفائدة المستمرة من وقف موارد مالية للمدرسة بدل الاكتفاء ببناء مبناها مرة واحدة؟","options":[{"id":"o2","text":"توقف المدرسة فور افتتاحها"},{"id":"o4","text":"تحويل التعليم إلى منفعة تخص المؤسس وحده"},{"id":"o3","text":"إلغاء الحاجة إلى المدرسين والكتب"},{"id":"o1","text":"توفير ما يضمن استمرار التعليم واستقبال طلاب جدد"}],"correct_id":"o1","explanation":"شرح الدرس تخصيص الوقفيات لضمان استمرار الدراسة وخدمة الأجيال.","page":134},{"id":"u03_l07_q155","lesson_id":"u03_l07","difficulty":"medium","prompt":"أي جهة أنشأت شراكة وقفية تعليمية حديثة لبناء المدارس في الأردن؟","options":[{"id":"o2","text":"وزارة السياحة وحدها"},{"id":"o3","text":"المنظمات الرياضية فقط"},{"id":"o1","text":"وزارتا التربية والتعليم والأوقاف والشؤون والمقدسات الإسلامية"},{"id":"o4","text":"أصحاب المصانع دون أي شراكة"}],"correct_id":"o1","explanation":"ذكر الكتاب الشراكة بين الوزارتين في وقفية التعليم لإنشاء مدارس.","page":135},{"id":"u03_l07_q157","lesson_id":"u03_l07","difficulty":"medium","prompt":"ما المجال الذي استهدفته وقفية السيدة زبيدة على طريق الحج؟","options":[{"id":"o3","text":"تأسيس مدارس لتعليم البرمجة"},{"id":"o1","text":"توفير المياه عبر الآبار والبرك والقنوات"},{"id":"o4","text":"تجهيز أسواق للتجارة فقط"},{"id":"o2","text":"إنشاء محاكم للميراث"}],"correct_id":"o1","explanation":"أورد الكتاب مشروعها لحفر الآبار وبناء الصهاريج وإيصال الماء للحجاج.","page":136},{"id":"u03_l07_q161","lesson_id":"u03_l07","difficulty":"medium","prompt":"ما الذي يميز الوقف عن مجرد تبرع يُستهلك مرة واحدة وفق تعريفه؟","options":[{"id":"o4","text":"تحويل المال الوقفي إلى ملك خاص لمشرفه"},{"id":"o2","text":"الاشتراط أن يُباع الأصل فورًا"},{"id":"o3","text":"انتهاء المنفعة بانتهاء أول مستفيد"},{"id":"o1","text":"تخصيص الأصل ليستمر الانتفاع بريعه في وجوه الخير"}],"correct_id":"o1","explanation":"عرّف الدرس الوقف باستدامة الأصل وجعل منفعته في الخير.","page":133},{"id":"u03_l07_q167","lesson_id":"u03_l07","difficulty":"hard","prompt":"كيف يسهم الوقف الاجتماعي في معالجة البطالة بدل الاقتصار على المساعدة العاجلة؟","options":[{"id":"o4","text":"بإلغاء حق المستفيدين في التدريب"},{"id":"o2","text":"بمنع المستفيدين من أي مشروع"},{"id":"o1","text":"بتمويل مشروعات صغيرة وتوفير فرص عمل مناسبة"},{"id":"o3","text":"بإبقاء كل مساعدة منقطعة بلا تطوير"}],"correct_id":"o1","explanation":"شرح الدرس دعم المشروعات وفرص العمل ضمن دور الوقف في حل البطالة.","page":136},{"id":"u03_l07_q172","lesson_id":"u03_l07","difficulty":"medium","prompt":"لماذا يُعد وقف بناء مدرسة ومكتبة مساهمة في حفظ العقل وتنمية المجتمع؟","options":[{"id":"o4","text":"لأنه يوقف الحركة العلمية عند جيل واحد"},{"id":"o2","text":"لأنه يمنع الطلاب من الوصول للكتب"},{"id":"o1","text":"لأنه ييسر التعلم ونشر المعرفة على نحو مستمر"},{"id":"o3","text":"لأنه يقتصر على تزين المباني بلا منفعة"}],"correct_id":"o1","explanation":"ربط الدرس المجال العلمي للوقف بنشر العلم وحفظ العقل.","page":134}]$wall_questions$::jsonb)
